//! A compact semantic qualification contract for Rust protocol tests.
//!
//! Production policy is generated by the Nix qualification module fixed point.
//! This fixture carries only synthetic identities and mandatory admission floors.

use anyhow::Result;
use aos_release::qualification::QualificationContract;
use serde_json::{Value, json};

/// Builds the smallest current qualification contract that exercises the
/// release protocol's mandatory admission semantics.
///
/// The production contract comes from the Nix module fixed point. This value
/// deliberately contains only synthetic test identities and the validation
/// floors required by [`QualificationContract::validate`].
pub fn contract() -> Result<QualificationContract> {
    let requirements = [
        ("ability-native-adapter-matrix", "staging", "release", true),
        ("ability-crucible-baseline", "staging", "release", false),
        ("ability-native-activation", "staging", "release", false),
        ("ability-native-kubernetes", "staging", "release", false),
        ("ability-native-recovery", "staging", "release", false),
        ("build-integrity", "build", "release", false),
        ("package-function", "staging", "packages", false),
        ("image-installation", "staging", "images", false),
        ("image-lifecycle", "staging", "images", false),
        ("image-update-recovery", "staging", "images", false),
        ("image-observation", "complete", "images", false),
        ("container-lifecycle", "staging", "containers", false),
        ("container-observation", "complete", "containers", false),
        ("staging-delivery", "staging", "release", false),
        ("operator-recovery", "staging", "release", false),
        ("production-recovery", "staging", "release", true),
        ("rollout-health", "rollout", "release", false),
        ("rollout-observation", "complete", "release", false),
    ]
    .into_iter()
    .map(|(id, phase, scope, production_only)| {
        let mut requirement = json!({
            "id": id,
            "phase": phase,
            "scope": scope,
            "method": "automated",
            "production_only": production_only,
            "checks": [format!("exercise-{id}")],
            "regressions": [],
            "invalidated_by": ["subject", "policy", "executor", "environment"],
            "measurements": measurements_for(id),
        });
        if id == "ability-native-adapter-matrix" {
            requirement["checks"] = json!(["native-adapter-matrix"]);
            requirement["matrix_spec"] = native_adapter_matrix_spec();
        }
        Ok(requirement)
    })
    .collect::<Result<Vec<_>>>()?;

    let image_targets = [
        ("disk-x86_64-linux", "x86_64-linux", "kvm", "q35"),
        ("disk-aarch64-linux", "aarch64-linux", "tcg", "virt"),
    ];
    let container_targets = [
        ("container-x86_64-linux", "x86_64-linux"),
        ("container-aarch64-linux", "aarch64-linux"),
    ];
    let targets = image_targets
        .map(|(id, platform, accelerator, machine)| {
            image_target(id, platform, accelerator, machine)
        })
        .into_iter()
        .chain(container_targets.map(|(id, platform)| container_target(id, platform)))
        .collect::<Vec<_>>();
    let claims = image_targets
        .iter()
        .flat_map(|(id, _, _, _)| claims_for(id, "image"))
        .chain(
            container_targets
                .iter()
                .flat_map(|(id, _)| claims_for(id, "container")),
        )
        .collect::<Vec<_>>();

    Ok(serde_json::from_value(json!({
        "schema_version": "aos.release.qualification-contract/v2",
        "id": "aos-system-v2",
        "promises": ["Exercise the release protocol fixture."],
        "exclusions": ["The synthetic fixture makes no production claim."],
        "thresholds": {
            "edge": threshold(86_400, false, false),
            "candidate": threshold(604_800, false, true),
            "stable": threshold(1_209_600, true, true),
            "emergency": threshold(1_209_600, true, true),
        },
        "targets": targets,
        "package_rules": [{
            "name": "fixture",
            "role": "general-catalog",
            "inherit_dependency_obligations": true,
        }],
        "requirements": requirements,
        "claims": claims,
        "support": {
            "default": {
                "kind": "standard",
                "superseded_after_trains": 2,
            },
            "trains": {},
        },
    }))?)
}

fn native_adapter_matrix_spec() -> Value {
    let descriptor = format!("sha256:{}", "a".repeat(64));
    let state_format = format!("sha256:{}", "b".repeat(64));
    let cell_id = "fixture/aos.fixture-effects/abi-1/apply/interrupt";
    let applicability = json!({
        "required_resource_lifetimes": [],
        "requires_state_format": false,
    });
    let disposition = json!({"kind": "exact", "value": "reconciled"});
    let postconditions = [json!({
        "evidence_kind": "journal-timeline",
        "name": "durable-attempt-state-classified",
    })];
    let adapter = json!({
        "adapter": "fixture",
        "conformance_families": ["durability-recovery"],
        "interface_abi": 1,
        "interface_descriptor": descriptor,
        "interface_name": "aos.fixture-effects",
        "methods": [{"method": "apply", "required_target_access": "exclusive-write"}],
        "observation_kind": "fixture-observation",
        "provider_contract": {
            "lifecycle": {"persistent_delete_method": null},
            "resource_lifetimes": ["persistent"],
            "state_format": state_format,
        },
        "provider_implementation": {
            "contract": "/nix/store/0123456789abcdfghijklmnpqrsvwxyz-fixture-contract",
            "implementation": "fixture-implementation",
            "observer": {
                "artifact": {
                    "path": "/nix/store/0123456789abcdfghijklmnpqrsvwxyz-fixture-observer",
                    "selector": {
                        "_type": "aos-package-output-selector",
                        "package": "fixture-observer",
                        "output": "out",
                    },
                },
                "entry_point": "bin/fixture-observer",
                "arguments": {"kind": "record"},
                "result": {"kind": "record"},
            },
        },
        "scope": "host-resource",
    });
    let scenario = json!({
        "applicability": applicability,
        "boundary": "after-acquisition",
        "candidate": "same",
        "disposition": disposition,
        "failure": "injected-interruption",
        "family": "durability-recovery",
        "id": "interrupt",
        "postconditions": postconditions,
        "predecessor": "same",
    });
    json!({
        "schema": "aos.qualification.native-adapter-matrix-spec/v1",
        "surface": {
            "adapters": [adapter],
            "families": ["durability-recovery"],
            "invalidation_dimensions": ["subject", "policy", "executor", "environment"],
            "matrix_schema": "aos.qualification.native-adapter-matrix/v1",
            "scenarios": [scenario],
            "schema": "aos.qualification.native-adapter-surface/v1",
        },
        "cells": [{
            "id": cell_id,
            "matrix_schema": "aos.qualification.native-adapter-matrix/v1",
            "adapter": "fixture",
            "interface": {"name": "aos.fixture-effects", "abi": 1, "descriptor": descriptor},
            "method": "apply",
            "required_target_access": "exclusive-write",
            "scope": "host-resource",
            "boundary": "after-acquisition",
            "failure": "injected-interruption",
            "predecessor": "same",
            "candidate": "same",
            "disposition": disposition,
            "applicability": applicability,
            "postconditions": ["durable-attempt-state-classified"],
            "postcondition_kinds": {"durable-attempt-state-classified": "journal-timeline"},
            "invalidated_by": ["subject", "policy", "executor", "environment"],
        }],
        "applicability": {
            "schema": "aos.qualification.native-adapter-matrix-applicability/v1",
            "applicable_cell_ids": [cell_id],
            "inapplicable_cells": [],
        },
    })
}

fn threshold(
    soak_seconds: u64,
    require_complete_matrix: bool,
    require_independent_review: bool,
) -> Value {
    json!({
        "exercise_max_age_seconds": 2_592_000,
        "require_complete_matrix": require_complete_matrix,
        "require_independent_review": require_independent_review,
        "soak_seconds": soak_seconds,
    })
}

fn measurements_for(requirement: &str) -> Value {
    match requirement {
        "image-installation" => json!({
            "reboot_cycles": {"minimum": 10, "maximum": null},
            "cold_boot_cycles": {"minimum": 3, "maximum": null},
        }),
        "image-update-recovery" => json!({
            "update_rollback_cycles": {"minimum": 3, "maximum": null},
        }),
        "container-lifecycle" => json!({
            "lifecycle_cycles": {"minimum": 10, "maximum": null},
        }),
        "image-observation" | "container-observation" => json!({
            "workload_operations": {"minimum": 1, "maximum": null},
            "data_integrity_failures": {"minimum": 0, "maximum": 0},
        }),
        _ => json!({}),
    }
}

fn image_target(id: &str, platform: &str, accelerator: &str, machine: &str) -> Value {
    json!({
        "id": id,
        "platform": platform,
        "kind": "image",
        "required": true,
        "environment": {
            "layers": [
                {
                    "platform": platform,
                    "backend": {"kind": "physical", "board": null, "chipset": null},
                    "cpu": empty_cpu_scope(),
                },
                {
                    "platform": platform,
                    "backend": {
                        "kind": "qemu",
                        "accelerator": accelerator,
                        "machine": machine,
                        "machine_version": null,
                        "version": null,
                        "cpu_model": null,
                    },
                    "cpu": empty_cpu_scope(),
                },
            ],
            "boot": "systemd-boot-uki",
            "security": {
                "secure_boot": true,
                "measured_boot": true,
                "verity": true,
                "encrypted_state": true,
                "persistent_firmware": true,
            },
            "resources": {"cpus": 2, "memory_mib": 8192, "disk_mib": 32768},
            "devices": [
                {
                    "stage": "initrd",
                    "driver": "virtio_blk",
                    "bus": null,
                    "vendor": null,
                    "product": null,
                    "revision": null,
                    "firmware": [],
                },
                {
                    "stage": "initrd",
                    "driver": "virtio_net",
                    "bus": null,
                    "vendor": null,
                    "product": null,
                    "revision": null,
                    "firmware": [],
                },
            ],
            "kernel_options": {"CONFIG_EFI": "y"},
        },
    })
}

fn container_target(id: &str, platform: &str) -> Value {
    json!({
        "id": id,
        "platform": platform,
        "kind": "container",
        "required": true,
        "environment": {
            "layers": [
                {
                    "platform": platform,
                    "backend": {"kind": "physical", "board": null, "chipset": null},
                    "cpu": empty_cpu_scope(),
                },
                {
                    "platform": platform,
                    "backend": {
                        "kind": "container",
                        "runtime": "containerd-runc",
                        "version": null,
                        "cgroup": null,
                        "network": null,
                        "volume": null,
                    },
                    "cpu": empty_cpu_scope(),
                },
            ],
            "boot": "linux-container",
            "security": {
                "secure_boot": false,
                "measured_boot": false,
                "verity": false,
                "encrypted_state": false,
                "persistent_firmware": false,
            },
            "resources": {"cpus": 1, "memory_mib": 0, "disk_mib": 0},
            "devices": [],
            "kernel_options": {},
        },
    })
}

fn empty_cpu_scope() -> Value {
    json!({"vendors": [], "models": [], "skus": [], "features": []})
}

fn claims_for(target: &str, kind: &str) -> [Value; 2] {
    let mut functions = match kind {
        "image" => vec![
            "image-installation",
            "image-lifecycle",
            "image-update-recovery",
        ],
        _ => vec!["container-lifecycle"],
    };
    let functional = json!({
        "id": format!("{target}-functional"),
        "target": target,
        "requirements": functions,
        "minimum_assurance": "A2",
        "phase": "staging",
        "blocks_release": true,
    });
    functions.push(if kind == "image" {
        "image-observation"
    } else {
        "container-observation"
    });
    let qualified = json!({
        "id": format!("{target}-qualified"),
        "target": target,
        "requirements": functions,
        "minimum_assurance": "A3",
        "phase": "complete",
        "blocks_release": true,
    });

    [functional, qualified]
}
